package com.example.shop.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.NamedAttributeNode;
import jakarta.persistence.NamedEntityGraph;
import java.lang.Long;
import java.lang.String;

@Entity
@NamedEntityGraph(name = "Gizmo.withTitle", attributeNodes = @NamedAttributeNode("title"))
public class Gizmo {

    @Id
    private Long id;

    @Column(name = "title")
    private String title;
}

package com.example.shop.dto;

public record GizmoDto(
        Long id,
        String title
) {
}

package com.example.shop.mapper;

import com.example.shop.domain.Gizmo;
import com.example.shop.dto.GizmoDto;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;

@Mapper
public interface GizmoMapper {
    @Mapping(source = "title", target = "title")
    GizmoDto toDto(Gizmo gizmo);
}
